package cn.zhuatech.scm;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;import java.util.regex.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class ScmApiIntegrationTests {@Autowired MockMvc mvc;private String login()throws Exception{String json=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"admin\",\"password\":\"admin123\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.user.role").value("ADMIN")).andReturn().getResponse().getContentAsString();Matcher m=Pattern.compile("\\\"token\\\":\\\"([^\\\"]+)\\\"").matcher(json);if(!m.find())throw new AssertionError("登录响应中缺少 token");return m.group(1);}@Test void adminCanReadDashboard()throws Exception{mvc.perform(get("/api/scm/dashboard").header("Authorization","Bearer "+login())).andExpect(status().isOk()).andExpect(jsonPath("$.data.openOrders").value(3)).andExpect(jsonPath("$.data.openAlerts").value(3));}@Test void adminCanCalculateInventoryCoverage()throws Exception{mvc.perform(post("/api/scm/inventory-coverage").header("Authorization","Bearer "+login()).contentType(MediaType.APPLICATION_JSON).content("{\"materialCode\":\"MAT-1001\",\"dailyDemand\":100,\"onHandQty\":300,\"inTransitQty\":200,\"safetyStock\":150,\"leadDays\":7}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.coverageDays").value(5.0)).andExpect(jsonPath("$.data.reorderPoint").value(850)).andExpect(jsonPath("$.data.shortageQty").value(350)).andExpect(jsonPath("$.data.status").value("CRITICAL"));}@Test void anonymousRequestIsDenied()throws Exception{mvc.perform(get("/api/scm/dashboard")).andExpect(status().isForbidden());}}
